    apple_url = f"{MOTOLITE_BASE_URL}/api/v1/motolite/wallet/apple/{warranty_public_id}"
    google_url = f"{MOTOLITE_BASE_URL}/api/v1/motolite/wallet/google/{warranty_public_id}"

