    model = html_lib.escape(str(payload.get("battery_model") or "—"))
    serial_number = html_lib.escape(str(payload.get("serial_number") or "—"))
    vehicle = html_lib.escape(str(payload.get("vehicle") or "—"))
    plate = html_lib.escape(str(payload.get("plate_number") or "—"))
    branch = html_lib.escape(str(payload.get("branch_name") or "—"))
    purchase_date = html_lib.escape(str(payload.get("purchase_date") or "—"))
    installation_date = html_lib.escape(str(payload.get("installation_date") or "—"))
    replacement_date = html_lib.escape(str(payload.get("recommended_replacement_date") or "—"))
    expires = html_lib.escape(str(payload.get("warranty_expires_at") or "—"))
    status = html_lib.escape(str(payload.get("warranty_display_status") or "ACTIVE"))
    warranty_months = html_lib.escape(str(payload.get("warranty_months") or "—"))
    days = payload.get("warranty_days_remaining")

    if days is None:
        remaining = "Warranty timing unavailable"
    elif days < 0:
        remaining = f"Expired {abs(days)} day{'s' if abs(days) != 1 else ''} ago"
    elif days == 0:
        remaining = "Expires today"
    else:
        remaining = f"{days} day{'s' if days != 1 else ''} remaining"

    emergency_number = str(payload.get("emergency_number") or "").strip()
    emergency_display = html_lib.escape(emergency_number)
    emergency_tel = re.sub(r"[^0-9+]", "", emergency_number)

    reminders = _member_reminders(member_public_id) if member_public_id else []
    activity = _member_activity(member_public_id) if member_public_id else []

