def _valid_hex_color(value: str, field_name: str) -> str:
    value = str(value or "").strip()
    if not re.fullmatch(r"#[0-9A-Fa-f]{6}", value):
        raise HTTPException(
            status_code=400,
            detail=f"{field_name} must use a 6-digit hex color such as #d71920.",
        )
    return value.lower()


def _wallet_rgb(value: str, fallback: str) -> str:
    color = str(value or fallback).strip()
    if not re.fullmatch(r"#[0-9A-Fa-f]{6}", color):
        color = fallback
    return f"rgb({int(color[1:3],16)},{int(color[3:5],16)},{int(color[5:7],16)})"



@motolite_router.post("/settings/card/upload-signature")
async def motolite_card_upload_signature(
    purpose: str = "logo",
    staff: dict = Depends(current_staff),
):
    """Create a short-lived signed Cloudinary upload for National branding assets."""
    _require_roles(staff, ROLE_NATIONAL)
    purpose = str(purpose or "logo").strip().lower()
    if purpose not in {"logo", "hero"}:
        raise HTTPException(status_code=400, detail="Upload purpose must be logo or hero.")
    if not (CLOUDINARY_CLOUD_NAME and CLOUDINARY_API_KEY and CLOUDINARY_API_SECRET):
        raise HTTPException(
            status_code=503,
            detail="Cloudinary is not configured for Motolite branding uploads.",
        )

    timestamp = int(datetime.utcnow().timestamp())
    folder = f"loyaltytree/motolite/branding/{purpose}"
    params = {
        "folder": folder,
        "timestamp": timestamp,
        "upload_preset": CLOUDINARY_UPLOAD_PRESET,
    }
    signature_base = "&".join(
        f"{key}={params[key]}" for key in sorted(params)
    ) + CLOUDINARY_API_SECRET
    signature = hashlib.sha1(signature_base.encode("utf-8")).hexdigest()

    return {
        "cloud_name": CLOUDINARY_CLOUD_NAME,
        "api_key": CLOUDINARY_API_KEY,
        "timestamp": timestamp,
        "signature": signature,
        "upload_preset": CLOUDINARY_UPLOAD_PRESET,
        "folder": folder,
        "purpose": purpose,
    }


