def _wallet_payload(wid: str):
    w = _require_record("motolite_warranties", wid, "Warranty")
    m = _require_record("motolite_members", w.get("member_public_id"), "Member")
    b = _require_record("motolite_batteries", w.get("battery_public_id"), "Battery")
    v = _get_one("motolite_vehicles", "public_id", w.get("vehicle_public_id")) if w.get("vehicle_public_id") else None
    branch = _get_one("motolite_branches", "public_id", w.get("original_branch_public_id")) if w.get("original_branch_public_id") else None

    expires = w.get("expires_at")
    days = _days_until(expires)
    status = str(w.get("status") or "active").lower()
    if days is not None and days < 0:
        display_status = "EXPIRED"
    elif status != "active":
        display_status = status.upper()
    elif days is not None and days <= 30:
        display_status = f"EXPIRES IN {max(days, 0)} DAYS"
    elif days is not None and days <= 60:
        display_status = "EXPIRING SOON"
    else:
        display_status = "ACTIVE"

    replacement = b.get("recommended_replacement_date")
    card_settings = _motolite_card_settings()
    emergency_settings = _motolite_emergency_settings()
    return {
        "member_public_id": m.get("public_id"),
        "member_number": m.get("member_number"),
        "member_name": m.get("name"),
        "battery_product": b.get("product_name"),
        "battery_model": b.get("model_code"),
        "serial_number": b.get("serial_number"),
        "purchase_date": b.get("purchase_date"),
        "installation_date": b.get("installation_date") or b.get("purchase_date"),
        "recommended_replacement_date": replacement,
        "vehicle": f"{v.get('make')} {v.get('model')}" if v else None,
        "plate_number": v.get("plate_number") if v else None,
        "branch_name": branch.get("name") if branch else None,
        "warranty_public_id": w.get("public_id"),
        "warranty_status": w.get("status"),
        "warranty_display_status": display_status,
        "warranty_expires_at": expires,
        "warranty_days_remaining": days,
        "warranty_months": w.get("warranty_months"),
        "qr_token": w.get("qr_token"),
        "qr_verification_url": f"{MOTOLITE_BASE_URL}/api/v1/motolite/warranty/verify/{w.get('qr_token')}",
        "verified_warranty_page_url": f"{MOTOLITE_BASE_URL}/api/v1/motolite/warranty/view/{w.get('qr_token')}",
        "activity_url": f"{MOTOLITE_BASE_URL}/api/v1/motolite/customer/activity/{w.get('qr_token')}",
        "emergency_number": emergency_settings.get("phone_number") or "",
        "emergency_button_label": emergency_settings.get("button_label") or "Call Customer Service",
        "emergency_help_text": emergency_settings.get("help_text") or "",
        "card_settings": card_settings,
        "latest_notification": (
            (_supabase().table("motolite_notifications").select("title,message,created_at")
             .eq("member_public_id", m.get("public_id"))
             .order("created_at", desc=True).limit(1).execute().data or [None])[0]
        ),
    }


def _google_class_id(): return f"{GOOGLE_WALLET_ISSUER_ID}.{MOTOLITE_GOOGLE_WALLET_CLASS_SUFFIX}"


def _ensure_google_class():
    try:
        import main as pm, httpx

        token = pm.get_google_access_token()
        if not token:
            return False

        cid = _google_class_id()
        headers = {
            "Authorization": f"Bearer {token}",
            "Content-Type": "application/json",
        }

        card = _motolite_card_settings()
        logo = (
            card.get("logo_url")
            or f"{MOTOLITE_BASE_URL}/api/v1/motolite/wallet/assets/motolite-logo.png"
        )

        class_fields = {
            "issuerName": "Motolite",
            "programName": str(card.get("card_title") or "Motolite Digital Warranty"),
            "hexBackgroundColor": str(card.get("background_color") or "#d71920"),
            "programLogo": {
                "sourceUri": {"uri": logo},
                "contentDescription": {
                    "defaultValue": {
                        "language": "en-US",
                        "value": "Motolite Pangmatagalan",
                    }
                },
            },
        }

        with httpx.Client(timeout=20) as c:
            current = c.get(
                f"https://walletobjects.googleapis.com/walletobjects/v1/loyaltyClass/{cid}",
                headers=headers,
            )

            if current.status_code == 200:
                # Do not leave an existing Motolite class stuck with the old
                # LoyaltyTree logo. PATCH branding every time we issue a pass.
                patch = c.patch(
                    f"https://walletobjects.googleapis.com/walletobjects/v1/loyaltyClass/{cid}",
                    headers=headers,
                    json=class_fields,
                )
                if patch.status_code in (200, 201):
                    return True
                print(
                    "MOTOLITE Google class branding PATCH failed:",
                    patch.status_code,
                    patch.text,
                )
                # Existing class itself is usable even if a branding refresh is
                # temporarily rejected by Google.
                return True

            create_body = {
                "id": cid,
                "reviewStatus": "UNDER_REVIEW",
                **class_fields,
            }
            created = c.post(
                "https://walletobjects.googleapis.com/walletobjects/v1/loyaltyClass",
                headers=headers,
                json=create_body,
            )
            return created.status_code in (200, 201, 409)

    except Exception as e:
        print("MOTOLITE Google class error", e)
        return False


def _google_object(wid: str):
    p = _wallet_payload(wid)
    card = p.get("card_settings") or _motolite_card_settings()
    wallet_page = f"{MOTOLITE_BASE_URL}/api/v1/motolite/wallet/{wid}"
    verified_page = p.get("verified_warranty_page_url") or wallet_page
    emergency_number = str(p.get("emergency_number") or "").strip()
    emergency_tel = re.sub(r"[^0-9+]", "", emergency_number)
    expires = str(p.get("warranty_expires_at") or "—")
    status = str(p.get("warranty_display_status") or "ACTIVE")

    text_modules = [{
        "id": "valid_until",
        "header": str(card.get("expiry_label") or "WARRANTY VALID UNTIL").upper(),
        "body": expires,
    }]
    if card.get("show_member_name", True):
        text_modules.append({"id":"customer","header":"MEMBER NAME","body":str(p.get("member_name") or "—")})
    if card.get("show_battery", True):
        text_modules.append({"id":"battery","header":"BATTERY","body":str(p.get("battery_product") or "—")})
    if card.get("show_serial", True):
        text_modules.append({"id":"serial","header":"SERIAL","body":str(p.get("serial_number") or "—")})
    if card.get("show_vehicle", True):
        text_modules.append({"id":"vehicle","header":"VEHICLE","body":str(p.get("vehicle") or "—")})
    if card.get("show_plate", True):
        text_modules.append({"id":"plate","header":"PLATE","body":str(p.get("plate_number") or "—")})
    if card.get("show_branch", True):
        text_modules.append({"id":"branch","header":"INSTALLATION BRANCH","body":str(p.get("branch_name") or "—")})
    if card.get("show_replacement", True):
        text_modules.append({"id":"replacement","header":"RECOMMENDED REPLACEMENT","body":str(p.get("recommended_replacement_date") or "—")})

    obj = {
        "id": f"{GOOGLE_WALLET_ISSUER_ID}.motolite_{wid}",
        "classId": _google_class_id(),
        "state": "active" if status != "EXPIRED" else "expired",
        "accountId": str(p.get("member_number") or ""),
        "accountName": "Motolite Member",
        "loyaltyPoints": {
            "label": str(card.get("warranty_label") or "Warranty"),
            "balance": {"string": status},
        },
        "barcode": {
            "type": "QR_CODE",
            "value": wallet_page,
            "alternateText": str(p.get("member_number") or ""),
        },
        "appLinkData": {
            "webAppLinkInfo": {
                "appTarget": {
                    "targetUri": {
                        "uri": wallet_page,
                        "description": "Open Motolite Digital Warranty",
                    }
                }
            },
            "displayText": {
                "defaultValue": {
                    "language": "en-US",
                    "value": "View Warranty & Activity",
                }
            },
        },
        "textModulesData": text_modules,
        "linksModuleData": {
            "uris": [
                {"uri": verified_page, "description": "Verified Warranty Details"},
                {"uri": f"{wallet_page}#activity", "description": "Motolite Activity & Reminders"},
            ]
        },
    }

    if emergency_tel:
        obj["linksModuleData"]["uris"].insert(0, {
            "uri": f"tel:{emergency_tel}",
            "description": str(p.get("emergency_button_label") or "Call Customer Service"),
        })

    if p.get("warranty_expires_at"):
        obj["validTimeInterval"] = {
            "end": {"date": f"{p['warranty_expires_at']}T23:59:59Z"}
        }

    wallet_hero_url = str(card.get("hero_url") or MOTOLITE_WALLET_HERO_URL or "").strip()
    if wallet_hero_url:
        obj["heroImage"] = {
            "sourceUri": {"uri": wallet_hero_url},
            "contentDescription": {
                "defaultValue": {
                    "language": "en-US",
                    "value": str(card.get("card_subtitle") or "Motolite Digital Battery Warranty"),
                }
            },
        }
    return obj


